// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }
    function testFuzz_property(address recipient, uint256 amount, uint256 firstCalls) public {
        vm.assume(recipient != address(0));
        uint256 calls = bound(firstCalls, 1, 3);
        for (uint256 i = 0; i < calls; i++) {
            c.newGrantProposal(recipient, amount);
        }
        assertTrue(c.proposalCount() == calls, "proposalCount must increase by one per grant proposal");
    }
}
